        if (carBox.maxX < brickBox.minX || carBox.minX > brickBox.maxX || carBox.maxY < brickBox.minY || carBox.minY > brickBox.maxY) continue;
        resolvePair(car, brick, satCollision(car, brick));
      }
    }
    bricks.forEach(resolveGround);
    if (runState === 'running') resolveGround(car);
  }
  if (!settleMode) updateSleeping(dt);
}

function updateSleeping(dt) {
  bricks.forEach((brick) => {
    if (brick.sleeping) return;
    const quiet = Math.hypot(brick.vx, brick.vy) < 0.055 && Math.abs(brick.angularVelocity) < 0.055;
    if (quiet) brick.sleepTimer += dt; else brick.sleepTimer = 0;
    if (brick.sleepTimer > 0.55) { brick.sleeping = true; brick.vx = 0; brick.vy = 0; brick.angularVelocity = 0; }
  });
}

function registerImpact(point, energy) {
  impactRegistered = true;
  impactShake = clamp(energy / 2600, 4, 14);
  impactFlash = 1;
  impactTag.classList.add('show');
  updateStatus('impact');
  window.setTimeout(() => impactTag.classList.remove('show'), 1300);
  const seed = Math.round(point.x * 1000);
  for (let i = 0; i < 46; i += 1) {
    const wave = (seed + i * 37) % 97 / 97;
    const angle = 2.6 + wave * 1.45;
    const speed = 1.2 + ((seed + i * 13) % 71) / 22;
    particles.push({ x: point.x + (wave - 0.5) * 0.7, y: Math.max(0.04, point.y + wave * 0.5), vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed + 0.3, life: 0.8 + wave * 0.8, maxLife: 1.6, size: 0.02 + wave * 0.035, color: i % 3 === 0 ? '#e0b887' : '#bd7657' });
  }
  for (let i = 0; i < 12; i += 1) particles.push({ x: point.x, y: 0.02, vx: -1.2 + i * 0.22, vy: 0.35 + (i % 4) * 0.12, life: 0.7 + i * 0.04, maxLife: 0.9, size: 0.025, color: '#9f8c76' });
}

function updateEffects(dt) {
  impactShake *= Math.pow(0.07, dt);
  impactFlash *= Math.pow(0.008, dt);
  particles.forEach((p) => { p.vy -= SETTINGS.gravity * 0.35 * dt; p.x += p.vx * dt; p.y += p.vy * dt; p.life -= dt; });
  particles = particles.filter((p) => p.life > 0 && p.y > -0.1);
  skidMarks.forEach((mark) => { mark.life -= dt * 0.08; });
  skidMarks = skidMarks.filter((mark) => mark.life > 0);
}

function updateTelemetry() {
  const carVelocity = Math.hypot(car.vx, car.vy);
  const moving = bricks.filter((brick) => !brick.sleeping && (Math.hypot(brick.vx, brick.vy) > 0.08 || Math.abs(brick.angularVelocity) > 0.08)).length;
  const settledRows = bricks.filter((brick) => Math.abs(brick.angle) < 0.22 && brick.y > 0.02 && brick.y < SETTINGS.brickHeight * (SETTINGS.rows + 0.5)).length;
  const integrity = Math.round((settledRows / bricks.length) * 100);
  telemetry.carSpeed.innerHTML = carVelocity.toFixed(1) + ' <small>m/s</small>';
  telemetry.time.innerHTML = elapsed.toFixed(2) + ' <small>s</small>';
  telemetry.moving.innerHTML = moving + ' <small>/ ' + bricks.length + '</small>';
